/* Enforce hidden attribute precedence */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #261738;
  --wood-main: #9c5c3d;
  --wood-dark: #63331b;
  --wood-light: #c9855b;
  --pixel-card: #3f2a58;
  --pixel-accent: #f4c264;
  --pixel-accent-hover: #ffdb8a;
  --text-main: #f8f0e5;
  --text-dim: #d1b89d;
  --border-shadow: #140d1e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-color);
  color: var(--text-main);
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1.5rem 1rem;
}

.shelf-app {
  width: 100%;
  max-width: 820px;
  background: var(--pixel-card);
  border: 4px solid var(--border-shadow);
  box-shadow: 6px 6px 0px 0px var(--border-shadow);
  padding: 2rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

.shelf-header {
  text-align: center;
}

.pixel-title {
  font-size: 2rem;
  font-weight: 800;
  color: var(--pixel-accent);
  letter-spacing: 2px;
  text-shadow: 3px 3px 0 var(--border-shadow);
}

.pixel-subtitle {
  color: var(--text-dim);
  font-size: 1rem;
  margin-top: 0.25rem;
}

.controls-card {
  background: var(--bg-color);
  border: 3px solid var(--border-shadow);
  box-shadow: 4px 4px 0 0 var(--border-shadow);
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.control-row {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.control-group {
  display: flex;
  flex-direction: column;
  flex: 1 1 200px;
  gap: 0.35rem;
}

.control-group-button {
  justify-content: flex-end;
}

.control-label {
  font-size: 0.95rem;
  font-weight: bold;
  color: var(--pixel-accent);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.pixel-input,
.pixel-select,
.pixel-button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  color: var(--text-main);
  background: var(--pixel-card);
  border: 3px solid var(--border-shadow);
  box-shadow: 3px 3px 0 0 var(--border-shadow);
  padding: 0.65rem 0.85rem;
  outline: none;
  transition: background-color 0.15s, transform 0.1s;
}

.pixel-input:hover,
.pixel-select:hover,
.pixel-button:hover {
  background: #50376d;
}

.pixel-input:focus-visible,
.pixel-select:focus-visible,
.pixel-button:focus-visible {
  border-color: var(--pixel-accent);
  outline: 2px dashed var(--pixel-accent);
  outline-offset: 2px;
}

.pixel-button {
  cursor: pointer;
  background: var(--wood-main);
  color: #fff;
  text-align: center;
}

.pixel-button:hover {
  background: var(--wood-light);
}

.pixel-button:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 0 var(--border-shadow);
}

.shelf-display {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.shelf-unit {
  background: #1e112a;
  border: 4px solid var(--border-shadow);
  padding: 1.5rem 1rem 0 1rem;
  box-shadow: inset 0 0 16px rgba(0, 0, 0, 0.6);
}

.book-grid {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 1.25rem 1rem;
  align-items: flex-end;
}

.book-item {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.pixel-book {
  min-height: 190px;
  background: var(--book-color, #7a3e3e);
  border: 3px solid var(--border-shadow);
  box-shadow: 3px -3px 0 0 rgba(255, 255, 255, 0.15) inset, 4px 4px 0 0 var(--border-shadow);
  padding: 0.85rem 0.6rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  position: relative;
  transition: transform 0.15s ease;
}

.pixel-book::before {
  content: '';
  position: absolute;
  left: 6px;
  top: 0;
  bottom: 0;
  width: 4px;
  background: rgba(0, 0, 0, 0.25);
}

.pixel-book:hover {
  transform: translateY(-4px);
}

.book-title {
  font-size: 0.95rem;
  font-weight: 800;
  line-height: 1.25;
  color: #ffffff;
  word-break: break-word;
  padding-left: 8px;
  text-shadow: 1px 1px 0 #000;
}

.book-meta {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding-left: 8px;
  border-top: 2px dashed rgba(255, 255, 255, 0.3);
  padding-top: 0.5rem;
}

.book-author {
  font-size: 0.8rem;
  color: #ffefcb;
  font-weight: 600;
  text-shadow: 1px 1px 0 #000;
}

.book-year {
  font-size: 0.8rem;
  font-weight: bold;
  display: inline-block;
  background: rgba(0, 0, 0, 0.4);
  padding: 0.1rem 0.3rem;
  border-radius: 2px;
  width: fit-content;
}

.shelf-board {
  height: 20px;
  background: var(--wood-main);
  border-top: 4px solid var(--wood-light);
  border-bottom: 4px solid var(--wood-dark);
  box-shadow: 0 4px 0 0 var(--border-shadow);
  margin: 0.5rem -1rem 0 -1rem;
}

.empty-alert {
  text-align: center;
  background: var(--wood-dark);
  color: var(--pixel-accent);
  font-weight: bold;
  padding: 1rem;
  border: 3px solid var(--border-shadow);
}

@media (max-width: 480px) {
  .shelf-app {
    padding: 1.25rem 0.75rem;
  }

  .pixel-title {
    font-size: 1.5rem;
  }

  .book-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 0.75rem;
  }

  .pixel-book {
    min-height: 170px;
  }
}

const BOOKS = [
  { id: 1, title: 'Neuromancer', author: 'William Gibson', year: 1984, color: '#32527b' },
  { id: 2, title: 'Snow Crash', author: 'Neal Stephenson', year: 1992, color: '#883e58' },
  { id: 3, title: 'Dune', author: 'Frank Herbert', year: 1965, color: '#a2622a' },
  { id: 4, title: 'Foundation', author: 'Isaac Asimov', year: 1951, color: '#396b52' },
  { id: 5, title: 'Solaris', author: 'Stanislaw Lem', year: 1961, color: '#68457c' },
  { id: 6, title: 'Ubik', author: 'Philip K. Dick', year: 1969, color: '#8b4f39' },
  { id: 7, title: 'Hyperion', author: 'Dan Simmons', year: 1989, color: '#2b5f63' },
  { id: 8, title: 'Left Hand of Darkness', author: 'Ursula K. Le Guin', year: 1969, color: '#5a4675' }
];

let sortField = 'title';
let isAscending = true;
let searchQuery = '';

const bookListElement = document.getElementById('book-list');
const searchInputElement = document.getElementById('search-input');
const sortBySelectElement = document.getElementById('sort-by');
const orderToggleButton = document.getElementById('order-toggle');
const emptyMessageElement = document.getElementById('empty-message');

function renderBooks() {
  const filtered = BOOKS.filter((book) => {
    const query = searchQuery.trim().toLowerCase();
    if (!query) return true;
    return (
      book.title.toLowerCase().includes(query) ||
      book.author.toLowerCase().includes(query)
    );
  });

  filtered.sort((a, b) => {
    let valA = a[sortField];
    let valB = b[sortField];

    if (typeof valA === 'string') {
      const comparison = valA.localeCompare(valB, undefined, { sensitivity: 'base' });
      return isAscending ? comparison : -comparison;
    }

    return isAscending ? valA - valB : valB - valA;
  });

  bookListElement.innerHTML = '';

  if (filtered.length === 0) {
    emptyMessageElement.hidden = false;
  } else {
    emptyMessageElement.hidden = true;

    filtered.forEach((book) => {
      const listItem = document.createElement('li');
      listItem.className = 'book-item';

      const bookArticle = document.createElement('article');
      bookArticle.className = 'pixel-book';
      bookArticle.style.setProperty('--book-color', book.color);

      const titleEl = document.createElement('h2');
      titleEl.className = 'book-title';
      titleEl.textContent = book.title;

      const metaDiv = document.createElement('div');
      metaDiv.className = 'book-meta';

      const authorEl = document.createElement('span');
      authorEl.className = 'book-author';
      authorEl.textContent = book.author;

      const yearEl = document.createElement('time');
      yearEl.className = 'book-year';
      yearEl.dateTime = String(book.year);
      yearEl.textContent = String(book.year);

      metaDiv.appendChild(authorEl);
      metaDiv.appendChild(yearEl);

      bookArticle.appendChild(titleEl);
      bookArticle.appendChild(metaDiv);
      listItem.appendChild(bookArticle);
      bookListElement.appendChild(listItem);
    });
  }
}

searchInputElement.addEventListener('input', (event) => {
  searchQuery = event.target.value;
  renderBooks();
});

sortBySelectElement.addEventListener('change', (event) => {
  sortField = event.target.value;
  renderBooks();
});

orderToggleButton.addEventListener('click', () => {
  isAscending = !isAscending;
  orderToggleButton.textContent = isAscending ? 'Ascending (▲)' : 'Descending (▼)';
  orderToggleButton.setAttribute('aria-label', `Toggle sort order: currently ${isAscending ? 'Ascending' : 'Descending'}`);
  renderBooks();
});

// Initial render
renderBooks();
